// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Look up an entry by its ID.
 * @param {string} entryId - e.g. "aesthetic_001"
 * @returns {{ category: string, title: string, index: number } | undefined}
 */
export function lookupEntry(entryId) {
  return CATEGORY_INDEX[entryId];
}

/**
 * Get all entry IDs for a given category.
 * @param {string} categoryKey - PascalCase key, e.g. "Aesthetic"
 * @returns {string[]}
 */
export function getEntryIdsForCategory(categoryKey) {
  const cat = CATEGORIES[categoryKey];
  return cat ? cat.entryIds : [];
}

/**
 * Resolve a preset into a map of { categoryKey: entryId }.
 * @param {string} presetId - e.g. "preset_001"
 * @returns {Object.<string, string> | undefined}
 */
export function getPresetSelections(presetId) {
  const preset = PRESETS.find(p => p.id === presetId);
  return preset ? preset.selections : undefined;
}

/**
 * Get total number of entries across all categories.
 * @returns {number}
 */
export function getTotalEntryCount() {
  return Object.keys(CATEGORY_INDEX).length;
}
